// Importer tests against the checked-in Swift fixture (tests/fixtures/swift-store-v1, generated by the Swift app).
import { DatabaseSync } from 'node:sqlite';
import { readFileSync, truncateSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { Db } from '../../../src/data/db';
import { coreDataToEpochMs, uuidFromBlob } from '../../../src/data/import/coreData';
import {
  importKeychain,
  LEGACY_NOTAM_SERVICE,
  type LegacySecretReader,
  type SecretStore,
} from '../../../src/data/import/keychain';
import { importStatus, runSwiftImport, type LegacyInputs } from '../../../src/data/import/runImport';
import { importSwiftStore, UnsupportedStoreError } from '../../../src/data/import/swiftStore';
import { importUserDefaults } from '../../../src/data/import/userDefaults';
import { migrate } from '../../../src/data/migrate';
import {
  aircraftRepository,
  flightPlanRepository,
  flightRecordRepository,
  logbookRepository,
  pilotRepository,
  settingsRepository,
} from '../../../src/data/repositories';
import { openNodeSqliteDb } from '../../support/nodeSqliteDb';
import { extractZip, FIXTURE_DIR, openNodeSqliteFileDb, parseBinaryPlist, readZip } from '../../support/swiftFixtures';

const zip = readZip(join(FIXTURE_DIR, 'swift-store-small.zip'));
const defaultsFixture = parseBinaryPlist(readFileSync(join(FIXTURE_DIR, 'user-defaults-small.plist'))) as Record<
  string,
  unknown
>;
const open = (variant: 'closed' | 'live') =>
  openNodeSqliteFileDb(join(extractZip(zip, `${variant}/support/`), 'default.store'));

async function freshTarget(): Promise<Db> {
  const db = openNodeSqliteDb();
  await migrate(db);
  return db;
}

describe('Core Data value decoding', () => {
  it('converts seconds since 2001 to epoch ms', () => {
    expect(coreDataToEpochMs(0)).toBe(978_307_200_000);
    expect(coreDataToEpochMs(757_468_800)).toBe(1_735_776_000_000); // 2025-01-02T00:00:00Z
    expect(coreDataToEpochMs(0.5)).toBe(978_307_200_500);
    expect(coreDataToEpochMs(null)).toBeNull();
    expect(coreDataToEpochMs('x')).toBeNull();
  });
  it('decodes a 16 byte UUID blob to lower case text and rejects other shapes', () => {
    expect(uuidFromBlob(Uint8Array.from([0, 0, 0, 1, 0, 0, 0x40, 0, 0x80, 0, 0, 0, 0, 0, 0, 1]))).toBe(
      '00000001-0000-4000-8000-000000000001',
    );
    expect(uuidFromBlob(new Uint8Array(15))).toBeNull();
    expect(uuidFromBlob('00000001-0000-4000-8000-000000000001')).toBeNull();
    expect(uuidFromBlob(null)).toBeNull();
  });
});

describe('SwiftData store import (fixture equality)', () => {
  it.each(['closed', 'live'] as const)('imports every model from the %s copy', async (variant) => {
    const target = await freshTarget();
    const r = await importSwiftStore(open(variant), target);
    expect(r.skipped).toEqual([]);
    expect(r.imported).toEqual({
      aircraft_profile: 3,
      pilot_profile: 2,
      flight_plan_record: 5,
      flight_record: 10,
      logbook_entry: 20,
      user_settings: 1,
    });
  });

  it('maps aircraft fields exactly', async () => {
    const target = await freshTarget();
    await importSwiftStore(open('closed'), target);
    const a = (await aircraftRepository(target).get('00000001-0000-4000-8000-000000000001'))!;
    expect(a).toEqual({
      id: '00000001-0000-4000-8000-000000000001',
      nNumber: 'N100KF',
      aircraftType: 'C172S',
      fuelCapacityGallons: 54,
      fuelBurnGPH: 9.5,
      cruiseSpeedKts: 115,
      icaoTypeDesignator: 'C172S',
      personsOnBoard: 2,
      vSpeeds: { vr: 55, vx: 62, vy: 74, va: 99, vne: 163, vfe: 85, vs0: 40, vs1: 48 },
      isActive: true,
      annualDue: 1_761_696_000_000,
      transponderDue: 1_753_056_000_000,
      createdAt: 1_735_776_000_000,
    });
    const second = (await aircraftRepository(target).get('00000001-0000-4000-8000-000000000002'))!;
    expect(second.vSpeeds).toEqual({ vr: null, vx: null, vy: 79, va: null, vne: 148, vfe: null, vs0: 44, vs1: null });
    expect(second.isActive).toBe(false);
  });

  it('maps pilots, converting night landing dates and keeping nulls', async () => {
    const target = await freshTarget();
    await importSwiftStore(open('closed'), target);
    const p1 = (await pilotRepository(target).get('00000002-0000-4000-8000-000000000001'))!;
    expect(p1).toMatchObject({
      name: 'Test Pilot One',
      certificateNumber: 'SEED-0001',
      certificateType: 'private',
      medicalClass: 'third',
      email: 'pilot1@example.invalid',
      phone: '+1 555 0100',
      totalHours: 412.5,
      isActive: true,
    });
    expect(p1.nightLandingEntries).toEqual([
      { date: coreDataToEpochMs(759_974_400), count: 2 },
      { date: coreDataToEpochMs(761_270_400), count: 1 },
    ]);
    const p2 = (await pilotRepository(target).get('00000002-0000-4000-8000-000000000002'))!;
    expect(p2).toMatchObject({ name: 'Test Pilot Two', totalHours: null, medicalExpiry: null, certificateType: null });
    expect(p2.nightLandingEntries).toEqual([]);
  });

  it('maps settings, keeping the stored region and lower-casing ids', async () => {
    const target = await freshTarget();
    await importSwiftStore(open('closed'), target);
    expect(await settingsRepository(target).get()).toMatchObject({
      defaultMapMode: 'trackUp',
      sectionalOpacity: 0.55,
      weatherRefreshInterval: 600,
      activeAircraftID: '00000001-0000-4000-8000-000000000001',
      activePilotID: '00000002-0000-4000-8000-000000000001',
      lastFlightPlanID: '00000003-0000-4000-8000-000000000002',
      regionRaw: 'us',
      createdAt: 1_735_689_600_000,
    });
  });

  it('keeps the same rows as the source for plans, flights and logbook (generic field check)', async () => {
    const source = open('closed');
    const target = await freshTarget();
    await importSwiftStore(source, target);
    const flights = await flightRecordRepository(target).list();
    const src = await source.all<Record<string, number | string | null>>('SELECT * FROM ZFLIGHTRECORD ORDER BY Z_PK');
    expect(flights).toHaveLength(src.length);
    for (const row of src) {
      const f = flights.find((x) => x.startDate === coreDataToEpochMs(row.ZSTARTDATE))!;
      expect(f).toBeDefined();
      expect(f.trackPointCount).toBe(row.ZTRACKPOINTCOUNT);
      expect(f.durationSeconds).toBe(row.ZDURATIONSECONDS);
      expect(f.departureICAO).toBe(row.ZDEPARTUREICAO);
      expect(f.endDate).toBe(coreDataToEpochMs(row.ZENDDATE));
      expect(f.hasDebrief).toBe(row.ZHASDEBRIEF === 1);
    }
    expect(flights.filter((f) => f.endDate === null)).toHaveLength(1);
    const plans = await flightPlanRepository(target).list();
    expect(plans).toHaveLength(5);
    const entries = await logbookRepository(target).list();
    expect(entries).toHaveLength(20);
    expect(entries.filter((e) => e.flightID !== null)).toHaveLength(10);
    const linked = entries.find((e) => e.flightID !== null)!;
    expect(flights.some((f) => f.id === linked.flightID)).toBe(true);
    expect(entries.find((e) => e.route === 'KPAO KSQL')).toMatchObject({
      aircraftType: 'SR22',
      pilotProfileID: '00000002-0000-4000-8000-000000000001',
    });
  });

  it('is idempotent and never overwrites edits made in the new app', async () => {
    const source = open('closed');
    const target = await freshTarget();
    await importSwiftStore(source, target);
    await aircraftRepository(target).update('00000001-0000-4000-8000-000000000001', { nNumber: 'N-EDITED' });
    await settingsRepository(target).update({ regionRaw: 'israel' });
    const again = await importSwiftStore(source, target);
    expect(Object.values(again.imported).reduce((a, b) => a + b, 0)).toBe(0);
    expect((await aircraftRepository(target).get('00000001-0000-4000-8000-000000000001'))!.nNumber).toBe('N-EDITED');
    expect((await settingsRepository(target).get())!.regionRaw).toBe('israel');
    expect(await aircraftRepository(target).list()).toHaveLength(3);
  });

  it('leaves the source store unmodified (read-only handle)', async () => {
    const source = open('closed');
    await expect(source.run('DELETE FROM ZLOGBOOKENTRY')).rejects.toThrow();
  });
});

describe('corrupt and unusual stores', () => {
  it('rejects an empty database as not a SwiftData store', async () => {
    const target = await freshTarget();
    await expect(importSwiftStore(openNodeSqliteDb(), target)).rejects.toBeInstanceOf(UnsupportedStoreError);
    expect(await target.all('SELECT * FROM aircraft_profile')).toEqual([]);
  });

  it('rejects a store with a model from a newer schema and imports nothing', async () => {
    const dir = extractZip(zip, 'closed/support/');
    const path = join(dir, 'default.store');
    const w = new DatabaseSync(path);
    w.exec("INSERT INTO Z_PRIMARYKEY (Z_ENT, Z_NAME, Z_SUPER, Z_MAX) VALUES (7, 'WeatherBriefing', 0, 0)");
    w.close();
    const target = await freshTarget();
    await expect(importSwiftStore(openNodeSqliteFileDb(path), target)).rejects.toThrow('WeatherBriefing');
    expect(await target.all('SELECT * FROM flight_record')).toEqual([]);
  });

  it('rejects a store whose table lost a column', async () => {
    const path = join(extractZip(zip, 'closed/support/'), 'default.store');
    const w = new DatabaseSync(path);
    w.exec('PRAGMA wal_checkpoint(TRUNCATE); ALTER TABLE ZPILOTPROFILE DROP COLUMN ZPHONE');
    w.close();
    await expect(importSwiftStore(openNodeSqliteFileDb(path), await freshTarget())).rejects.toThrow('ZPHONE');
  });

  it('skips a row with an unreadable id, drops unreadable JSON, and reports both', async () => {
    const path = join(extractZip(zip, 'closed/support/'), 'default.store');
    const w = new DatabaseSync(path);
    w.exec(
      "PRAGMA wal_checkpoint(TRUNCATE); UPDATE ZAIRCRAFTPROFILE SET ZID = X'0102' WHERE Z_PK = 2; UPDATE ZAIRCRAFTPROFILE SET ZVSPEEDSDATA = X'7B6E6F' WHERE Z_PK = 3",
    );
    w.close();
    const target = await freshTarget();
    const r = await importSwiftStore(openNodeSqliteFileDb(path), target);
    expect(r.imported.aircraft_profile).toBe(2);
    expect(r.skipped.map((s) => s.reason)).toEqual([
      'ZID unreadable; row skipped',
      'ZVSPEEDSDATA unreadable; value dropped',
    ]);
    expect((await aircraftRepository(target).list()).map((a) => a.vSpeeds === null)).toEqual([false, true]);
  });

  it('survives a truncated -wal: imports without error, never more than the full store', async () => {
    const dir = extractZip(zip, 'closed/support/');
    truncateSync(join(dir, 'default.store-wal'), 4096);
    const target = await freshTarget();
    const r = await importSwiftStore(openNodeSqliteFileDb(join(dir, 'default.store')), target);
    expect(r.imported.logbook_entry).toBeLessThanOrEqual(20);
    expect(r.imported.user_settings).toBeLessThanOrEqual(1);
  });

  it('a store file that is not sqlite fails to open and leaves the target untouched', async () => {
    const dir = extractZip(zip, 'closed/support/');
    writeFileSync(join(dir, 'garbage.store'), Buffer.from('this is not a database'.repeat(50)));
    const target = await freshTarget();
    await expect(importSwiftStore(openNodeSqliteFileDb(join(dir, 'garbage.store')), target)).rejects.toBeDefined();
    expect(await target.all('SELECT * FROM aircraft_profile')).toEqual([]);
  });

  it('keeps an existing settings row instead of importing a second one', async () => {
    const target = await freshTarget();
    await settingsRepository(target).update({ regionRaw: 'israel' });
    const r = await importSwiftStore(open('closed'), target);
    expect(r.imported.user_settings).toBe(0);
    expect((await settingsRepository(target).get())!.regionRaw).toBe('israel');
  });
});

describe('UserDefaults import', () => {
  it('imports the known keys from the fixture and ignores the rest', async () => {
    const target = await freshTarget();
    const r = await importUserDefaults(
      { ...defaultsFixture, 'com.apple.unrelated': 1, simulateDatabaseFailure: true },
      target,
    );
    expect(r.imported).toBe(Object.keys(defaultsFixture).length);
    expect(r.ignored.sort()).toEqual(['com.apple.unrelated', 'simulateDatabaseFailure']);
    const rows = await target.all<{ key: string; value: string }>(
      'SELECT key, value FROM app_preferences ORDER BY key',
    );
    const map = Object.fromEntries(rows.map((x) => [x.key, JSON.parse(x.value)]));
    expect(map).toMatchObject({
      hasSeenOnboarding: true,
      displayMode: 'night',
      telemetryEnabled: false,
      showsFlightLog: false,
      showsInstruments: false,
      showsPredictions: true,
      showAirportDiagrams: false,
      israelChartHintDismissed: true,
      israelOffRouteThresholdNM: 2.5,
      israelNotamReadKeys: ['seed-notam-a', 'seed-notam-b'],
      'israel.routeNetwork.00000001-0000-4000-8000-000000000001': 'cvfr',
      'israel.routeNetwork.00000001-0000-4000-8000-000000000002': 'lsa',
    });
  });
  it('is idempotent and keeps a value changed after the first import', async () => {
    const target = await freshTarget();
    await importUserDefaults({ displayMode: 'night' }, target);
    await target.run("UPDATE app_preferences SET value = '\"day\"' WHERE key = 'displayMode'");
    const again = await importUserDefaults({ displayMode: 'night' }, target);
    expect(again.imported).toBe(0);
    expect(await target.get('SELECT value FROM app_preferences WHERE key = ?', ['displayMode'])).toEqual({
      value: '"day"',
    });
  });
  it('ignores values of an unexpected type', async () => {
    const target = await freshTarget();
    const r = await importUserDefaults(
      { displayMode: { a: 1 }, telemetryEnabled: NaN, israelNotamReadKeys: [1] },
      target,
    );
    expect(r.imported).toBe(0);
    expect(r.ignored).toHaveLength(3);
  });
});

function fakeSecrets(initial: Record<string, string>) {
  const legacy = new Map(Object.entries(initial));
  const store = new Map<string, string>();
  const calls: string[] = [];
  const reader: LegacySecretReader = {
    async read(service, account) {
      expect(service).toBe(LEGACY_NOTAM_SERVICE);
      return legacy.get(account) ?? null;
    },
    async delete(service, account) {
      expect(service).toBe(LEGACY_NOTAM_SERVICE);
      calls.push(`delete ${account}`);
      legacy.delete(account);
    },
  };
  const secretStore: SecretStore = {
    async get(key) {
      return store.get(key) ?? null;
    },
    async set(key, value) {
      calls.push(`set ${key}`);
      store.set(key, value);
    },
  };
  return { legacy, store, calls, reader, secretStore };
}

describe('keychain step', () => {
  it('moves both items: writes through the store first, then deletes the legacy item', async () => {
    const f = fakeSecrets({ client_id: 'id-1', client_secret: 'secret-1' });
    const r = await importKeychain(f.reader, f.secretStore);
    expect(r).toEqual({ moved: ['client_id', 'client_secret'], absent: [], failed: [] });
    expect(f.store.get('faa-notam.client_id')).toBe('id-1');
    expect(f.store.get('faa-notam.client_secret')).toBe('secret-1');
    expect(f.legacy.size).toBe(0);
    expect(f.calls).toEqual([
      'set faa-notam.client_id',
      'delete client_id',
      'set faa-notam.client_secret',
      'delete client_secret',
    ]);
  });
  it('reports absent items and is idempotent', async () => {
    const f = fakeSecrets({ client_id: 'id-1' });
    expect((await importKeychain(f.reader, f.secretStore)).absent).toEqual(['client_secret']);
    const again = await importKeychain(f.reader, f.secretStore);
    expect(again).toEqual({ moved: [], absent: ['client_id', 'client_secret'], failed: [] });
  });
  it('keeps the legacy item when the new write fails, and when the read-back differs', async () => {
    const f = fakeSecrets({ client_id: 'id-1', client_secret: 's' });
    const realSet = f.secretStore.set;
    f.secretStore.set = async (key, value) => {
      if (key.endsWith('client_id')) throw new Error('keystore locked');
      if (key.endsWith('client_secret')) return void (await realSet(key, 'garbled'));
      return realSet(key, value);
    };
    const r = await importKeychain(f.reader, f.secretStore);
    expect(r.failed).toEqual(['client_id', 'client_secret']);
    expect(f.legacy.size).toBe(2);
  });
  it('does not overwrite a value the user already entered in the new app', async () => {
    const f = fakeSecrets({ client_id: 'old' });
    f.store.set('faa-notam.client_id', 'typed-by-user');
    await importKeychain(f.reader, f.secretStore);
    expect(f.store.get('faa-notam.client_id')).toBe('typed-by-user');
    expect(f.legacy.has('client_id')).toBe(false);
  });
});

describe('runSwiftImport', () => {
  const inputs = (secrets: ReturnType<typeof fakeSecrets> | null): LegacyInputs => ({
    store: open('closed'),
    defaults: defaultsFixture,
    secrets: secrets && { reader: secrets.reader, store: secrets.secretStore },
  });

  it('runs every step once, marks them complete, and does nothing on a re-run', async () => {
    const target = await freshTarget();
    const f = fakeSecrets({ client_id: 'a', client_secret: 'b' });
    const first = await runSwiftImport(target, inputs(f), () => 1000);
    expect(first.status).toBe('complete');
    expect(first.ran).toEqual(['swift-store', 'user-defaults', 'keychain']);
    expect(await importStatus(target)).toBe('complete');
    const second = await runSwiftImport(target, inputs(f), () => 2000);
    expect(second).toEqual({ status: 'complete', ran: [], failed: [] });
    expect(await target.all('SELECT * FROM aircraft_profile')).toHaveLength(3);
  });

  it('fresh install: no legacy data marks every step complete with nothing imported', async () => {
    const target = await freshTarget();
    const r = await runSwiftImport(target, { store: null, defaults: null, secrets: null });
    expect(r.status).toBe('complete');
    expect(await importStatus(target)).toBe('complete');
    expect(await target.all('SELECT * FROM aircraft_profile')).toEqual([]);
  });

  it('a failing store step is recorded, the other steps still run, and a retry completes it', async () => {
    const target = await freshTarget();
    const f = fakeSecrets({ client_id: 'a' });
    const bad: LegacyInputs = { ...inputs(f), store: openNodeSqliteDb() };
    const first = await runSwiftImport(target, bad);
    expect(first.status).toBe('failed');
    expect(first.failed.map((x) => x.step)).toEqual(['swift-store']);
    expect(first.ran).toEqual(['swift-store', 'user-defaults', 'keychain']);
    expect(await importStatus(target)).toBe('incomplete');
    expect(await target.get("SELECT status FROM migration_state WHERE step = 'swift-store'")).toEqual({
      status: 'failed',
    });
    const retry = await runSwiftImport(target, inputs(f));
    expect(retry.status).toBe('complete');
    expect(retry.ran).toEqual(['swift-store']);
    expect(await importStatus(target)).toBe('complete');
  });

  it('a keychain failure leaves legacy items and reports failed until retried', async () => {
    const target = await freshTarget();
    const f = fakeSecrets({ client_id: 'a' });
    const realSet = f.secretStore.set;
    f.secretStore.set = async () => {
      throw new Error('no');
    };
    const first = await runSwiftImport(target, inputs(f));
    expect(first.failed.map((x) => x.step)).toEqual(['keychain']);
    expect(f.legacy.has('client_id')).toBe(true);
    f.secretStore.set = realSet;
    expect((await runSwiftImport(target, inputs(f))).status).toBe('complete');
    expect(f.legacy.size).toBe(0);
  });
});
